INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('3fddf21c-c69c-4f0b-b17e-bd9974557fd4', '0876482d-03e1-5b79-a5b8-82328a309d2a', 'nl', 'Coral', 'Mobiel huis van 57 m² met een ruime woonkamer en open kitchenette, twee slaapkamers, een badkamer met douche en praktische bergruimte. Een groot terras verlengt de woonruimte naar buiten. Geschikt voor een perceel, om het hele jaar te wonen of als verhuurunit in een toeristische accommodatie.', '2026-11-20T16:32:34.343Z'::timestamptz, '2026-11-20T17:38:44.382Z'::timestamptz, '[{"id":"a396fd88-fb39-54c6-a15e-65bf83122ea1","name":"Woonkamer met kitchenette"},{"id":"5b268a60-de34-5dfe-a5e1-d3d15ce7b039","name":"Slaapkamer"},{"id":"59ae6afd-06e1-560c-a029-589735756c5d","name":"Slaapkamer 2"},{"id":"14e31ebb-fa6c-504a-a0f3-bb0f50f07944","name":"Badkamer"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, 'Een vlakke, voorbereide ondergrond; de klant bereidt standplaats en toegang voor.', NULL, 'Stalen frame, wanden van AGNES-platen en waterdichte Fibo-panelen.', 'Zadeldak', 'Interieur en afwerking naar keuze; te kiezen zijn daktype, terras en verwarming (gas, elektrisch, vloerverwarming of airco).', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('a50acd31-863a-4f36-8c23-5e52b80c2977', '0f9c798d-4775-5f24-a928-be120e16b370', 'de', 'Aurora', 'Geräumiges mobiles Haus mit ca. 60 m² (ca. 15 × 4,8 m), großem Wohnzimmer mit Küchenzeile, zwei Schlafzimmern, separater Ankleide am Hauptschlafzimmer, Bad mit Dusche und Hauswirtschaftsraum mit Platz für eine Waschmaschine. Ein zentraler Flur ordnet den Grundriss, ein Ausgang zur Terrasse erweitert den Wohnbereich. Für ganzjähriges Wohnen gedacht, für Familien ebenso wie für touristische Investitionen.', '2026-11-20T16:32:34.443Z'::timestamptz, '2026-11-20T17:38:44.539Z'::timestamptz, '[{"id":"b8237efe-ff51-58d1-a192-6c5f4bdf4015","name":"Wohnzimmer mit Küchenzeile"},{"id":"f9a41e42-244f-5c0f-afaf-ac1d22dd30d2","name":"Schlafzimmer"},{"id":"c0364fd3-75f5-54f1-a348-a2c78b663df8","name":"Schlafzimmer 2"},{"id":"428acff5-6d4a-5d85-a0cc-2574751ad4a0","name":"Badezimmer"},{"id":"fc342c88-db19-5697-ad68-791acc3c1f71","name":"Flur"},{"id":"ff866b5f-8559-5c73-abbc-760f53ed7a67","name":"Ankleide"},{"id":"a134b0b4-1ef3-5996-abbd-d14a7eeec9d6","name":"Hauswirtschaftsraum"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, 'Ebener, vorbereiteter Untergrund; Stellplatz und Zufahrt bereitet der Kunde vor.', NULL, 'Stahlrahmen, Wände aus AGNES-Platten und wasserfesten Fibo-Paneelen.', 'Pultdach', 'Innenraum und Oberflächen konfigurierbar; wählbar sind Dachform, Terrasse und Heizung (Gas, Strom, Fußbodenheizung oder Klimaanlage).', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('d4ee85bd-8752-4657-80e3-6bd98bac9e9d', '0f9c798d-4775-5f24-a928-be120e16b370', 'nl', 'Aurora', 'Ruim mobiel huis van ca. 60 m² (ca. 15 × 4,8 m) met een grote woonkamer met kitchenette, twee slaapkamers, een aparte inloopkast bij de hoofdslaapkamer, een badkamer met douche en een bijkeuken met plaats voor een wasmachine. Een centrale gang ordent de indeling en een uitgang naar het terras vergroot de leefruimte. Bedoeld voor gebruik het hele jaar, voor gezinnen en toeristische investeringen.', '2026-11-20T16:32:34.443Z'::timestamptz, '2026-11-20T17:38:44.539Z'::timestamptz, '[{"id":"b8237efe-ff51-58d1-a192-6c5f4bdf4015","name":"Woonkamer met kitchenette"},{"id":"f9a41e42-244f-5c0f-afaf-ac1d22dd30d2","name":"Slaapkamer"},{"id":"c0364fd3-75f5-54f1-a348-a2c78b663df8","name":"Slaapkamer 2"},{"id":"428acff5-6d4a-5d85-a0cc-2574751ad4a0","name":"Badkamer"},{"id":"fc342c88-db19-5697-ad68-791acc3c1f71","name":"Gang"},{"id":"ff866b5f-8559-5c73-abbc-760f53ed7a67","name":"Inloopkast"},{"id":"a134b0b4-1ef3-5996-abbd-d14a7eeec9d6","name":"Bijkeuken"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, 'Een vlakke, voorbereide ondergrond; de klant bereidt standplaats en toegang voor.', NULL, 'Stalen frame, wanden van AGNES-platen en waterdichte Fibo-panelen.', 'Lessenaarsdak', 'Interieur en afwerking naar keuze; te kiezen zijn daktype, terras en verwarming (gas, elektrisch, vloerverwarming of airco).', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('ce03ee12-10b4-4d41-a2b9-4e43b6050332', '66491459-a5b3-5be1-a9f0-f6f1d2b69d29', 'de', 'Horizon', 'Mobiles Haus mit 61,5 m² Nutzfläche (76,5 m² bebaute Fläche), drei Schlafräumen, zwei Bädern und separatem WC. Die Küche hat einen hohen Kühlschrank, Induktionskochfeld, Mikrowelle mit Backofenfunktion, eingebaute Dunstabzugshaube und 45 cm Geschirrspüler; zwei Schlafzimmer haben 160 cm Betten mit Bettkasten, der dritte Raum Bett und Schreibtisch. Zentralheizung, Mineralwolldämmung mit 20 cm in Dach und Boden und 15 cm in den Wänden, Vorbereitung für einen Warmwasserspeicher.', '2026-11-20T16:32:34.555Z'::timestamptz, '2026-11-20T17:38:44.704Z'::timestamptz, '[{"id":"1f65a5f2-c8d6-537f-a05c-158a5418a2df","name":"Wohnzimmer mit Küchenzeile"},{"id":"2d4ea31b-9a32-5d56-a0e2-b7c28bf913bc","name":"Schlafzimmer"},{"id":"4646ce97-2042-53fa-a172-b62d751c0029","name":"Schlafzimmer 2"},{"id":"d6920ad0-255d-524a-ac28-decf294423f2","name":"Zimmer"},{"id":"8d35e038-d475-5e4e-a2c6-a7d5716756f8","name":"Badezimmer"},{"id":"af2f4486-c69b-5ea7-a8cc-8220f2f66538","name":"Badezimmer 2"},{"id":"d9322c83-e854-5554-aa61-36b864433612","name":"WC"},{"id":"502fbf29-ca42-5319-a9b5-cc8c7d818b1d","name":"Flur"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, 'Ebener, vorbereiteter Untergrund; Stellplatz und Zufahrt bereitet der Kunde vor.', NULL, 'Stahlrahmen, Wände aus AGNES-Platten und wasserfesten Fibo-Paneelen.', 'Flachdach', 'Innenraum und Oberflächen konfigurierbar; wählbar sind Dachform, Terrasse und Heizung (Gas, Strom, Fußbodenheizung oder Klimaanlage).', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('2908f98a-aaa7-4334-af57-615c910e61da', '66491459-a5b3-5be1-a9f0-f6f1d2b69d29', 'nl', 'Horizon', 'Mobiel huis met 61,5 m² gebruiksoppervlakte (76,5 m² bebouwde oppervlakte), drie slaapruimtes, twee badkamers en een apart toilet. De keuken heeft een hoge koelkast, inductiekookplaat, magnetron met ovenfunctie, ingebouwde afzuigkap en een vaatwasser van 45 cm; twee slaapkamers hebben bedden van 160 cm met beddengoedlade, de derde kamer een bed en een bureau. Centrale verwarming, isolatie van minerale wol van 20 cm in dak en vloer en 15 cm in de wanden, voorbereid voor een boiler.', '2026-11-20T16:32:34.555Z'::timestamptz, '2026-11-20T17:38:44.704Z'::timestamptz, '[{"id":"1f65a5f2-c8d6-537f-a05c-158a5418a2df","name":"Woonkamer met kitchenette"},{"id":"2d4ea31b-9a32-5d56-a0e2-b7c28bf913bc","name":"Slaapkamer"},{"id":"4646ce97-2042-53fa-a172-b62d751c0029","name":"Slaapkamer 2"},{"id":"d6920ad0-255d-524a-ac28-decf294423f2","name":"Kamer"},{"id":"8d35e038-d475-5e4e-a2c6-a7d5716756f8","name":"Badkamer"},{"id":"af2f4486-c69b-5ea7-a8cc-8220f2f66538","name":"Badkamer 2"},{"id":"d9322c83-e854-5554-aa61-36b864433612","name":"Toilet"},{"id":"502fbf29-ca42-5319-a9b5-cc8c7d818b1d","name":"Gang"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, 'Een vlakke, voorbereide ondergrond; de klant bereidt standplaats en toegang voor.', NULL, 'Stalen frame, wanden van AGNES-platen en waterdichte Fibo-panelen.', 'Plat dak', 'Interieur en afwerking naar keuze; te kiezen zijn daktype, terras en verwarming (gas, elektrisch, vloerverwarming of airco).', NULL) ON CONFLICT DO NOTHING;
